// Offset pagination: simple, and broken when rows are inserted while you page.
function listPage(rows, { limit = 20, cursor } = {}) {
  const sorted = [...rows].sort((a, b) => (a.createdAt < b.createdAt ? 1 : a.createdAt > b.createdAt ? -1 : 0));
  const offset = cursor ? Number(atob(cursor)) : 0;
  const items = sorted.slice(offset, offset + limit);
  const next = offset + limit;
  return { items, nextCursor: next < sorted.length ? btoa(String(next)) : null };
}

