const MAX_LIMIT = 100;

// Newest first; ties on createdAt broken by id, so no two rows are "equal".
function compare(a, b) {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? 1 : -1;
  if (a.id !== b.id) return a.id < b.id ? 1 : -1;
  return 0;
}

function encodeCursor(row) {
  return btoa(JSON.stringify([row.createdAt, row.id]));
}

function decodeCursor(cursor) {
  try {
    const [createdAt, id] = JSON.parse(atob(cursor));
    if (typeof createdAt !== 'string' || typeof id !== 'string') throw new Error('shape');
    return { createdAt, id };
  } catch (e) {
    throw new Error('invalid cursor');
  }
}

function listPage(rows, { limit = 20, cursor } = {}) {
  limit = Math.min(Math.max(1, Math.floor(limit)), MAX_LIMIT);
  let sorted = [...rows].sort(compare);
  if (cursor != null) {
    const after = decodeCursor(cursor);
    // SQL: WHERE (created_at, id) < ($1, $2) ORDER BY created_at DESC, id DESC
    sorted = sorted.filter((r) => compare(r, after) > 0);
  }
  // Fetch one extra row to learn whether another page exists.
  const page = sorted.slice(0, limit + 1);
  const items = page.slice(0, limit);
  const nextCursor = page.length > limit ? encodeCursor(items[items.length - 1]) : null;
  return { items, nextCursor };
}

