const mk = (n, startDay = 1) => Array.from({ length: n }, (_, i) => ({ id: 's' + String(i + 1).padStart(3, '0'), createdAt: '2026-09-' + String(startDay + i).padStart(2, '0') + 'T08:00:00Z', minutes: 10 + i }));
const rows = mk(10);
const p = listPage(rows, { limit: 3 });
assertEqual(p.items.map(r => r.id), ['s010', 's009', 's008']);
assert(typeof p.nextCursor === 'string' && p.nextCursor.length > 0, 'nextCursor should be a non-empty string');

const mk = (n, startDay = 1) => Array.from({ length: n }, (_, i) => ({ id: 's' + String(i + 1).padStart(3, '0'), createdAt: '2026-09-' + String(startDay + i).padStart(2, '0') + 'T08:00:00Z', minutes: 10 + i }));
const rows = mk(10);
const seen = []; let cursor; let pages = 0;
do { const p = listPage(rows, { limit: 3, cursor }); seen.push(...p.items.map(r => r.id)); cursor = p.nextCursor; pages++; } while (cursor && pages < 20);
assertEqual(pages, 4, 'pages');
assertEqual(seen, ['s010','s009','s008','s007','s006','s005','s004','s003','s002','s001']);

